// === STATE =============================================================
// Define initial game state objects.
const player = { x: 400, y: 300, radius: 10 };
const hazards = []; // will hold obstacle objects
let score = 0;
let phase = "playing"; // "playing" | "gameover"
// === END STATE =========================================================

// === CONFIG =============================================================
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
let loopId = null;
let lastTime = performance.now();
// === END CONFIG =========================================================

// === LOOP ===============================================================
function startLoop() {
  if (loopId !== null) cancelAnimationFrame(loopId);
  function tick(now) {
    try {
      const dt = Math.min((now - lastTime) / 1000, 0.1);
      lastTime = now;
      // placeholder update/render
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    } catch (err) {
      console.error("loop error", err);
    }
    loopId = requestAnimationFrame(tick);
  }
  loopId = requestAnimationFrame(tick);
}
// === END LOOP ===========================================================

// Start the game
startLoop();

// Game script will be added in subsequent tasks.

